    @Test
    void revokeRemovesPublicDisplayButKeepsVersionAndReason() throws Exception {
        createObservation("req-v1", "obs-1").andExpect(status().isCreated());
        registerAttachment("req-v2", "obs-1", "att-1", "原始摘要").andExpect(status().isCreated());
