        // 无角色 / 非证据角色 → 403
        getVersionView("obs-1", "att-1", 1, null).andExpect(status().isForbidden());
        getVersionView("obs-1", "att-1", 1, "REDACTOR").andExpect(status().isForbidden());

        // 证据角色：version 0 读原始摘要，version 1 读脱敏版本
